def rename_values(forward: bool) -> None:
    for table, column, old, new in RENAMED:
        before, after = (old, new) if forward else (new, old)
        op.execute(f"UPDATE {table} SET {column} = '{after}' WHERE {column} = '{before}'")


def move_areas(forward: bool) -> None:
    for kind, old, new in MOVED_AREAS:
        op.execute(f"UPDATE law_profiles SET area = '{new if forward else old}' WHERE kind = '{kind}'")


