def add_checks(forward: bool) -> None:
    for table, name, text in CHECKS:
        with op.batch_alter_table(table, schema=None) as batch_op:
            if forward:
                batch_op.create_check_constraint(batch_op.f(name), text)
            else:
                batch_op.drop_constraint(batch_op.f(name), type_="check")


